'use client';

import { IconPlaceholder } from '@/components/icon-placeholder';
import { useEditor, useEditorHistory } from 'platejs/react';
import * as React from 'react';

import { ToolbarButton } from '@/registry/components/editor/toolbar';

export function RedoToolbarButton(
  props: React.ComponentProps<typeof ToolbarButton>
) {
  const { canRedo, pending, redo } = useEditorHistory({ editor: useEditor() });

  return (
    <ToolbarButton
      {...props}
      aria-busy={pending !== null}
      disabled={!canRedo}
      onClick={redo}
      tooltip="Redo"
    >
      <IconPlaceholder lucide="Redo2Icon" tabler="IconArrowForwardUp" hugeicons="Redo02Icon" phosphor="ArrowUUpRightIcon" remixicon="RiArrowGoForwardLine" className="[&:dir(rtl)]:-scale-x-100" />
    </ToolbarButton>
  );
}

export function UndoToolbarButton(
  props: React.ComponentProps<typeof ToolbarButton>
) {
  const { canUndo, pending, undo } = useEditorHistory({ editor: useEditor() });

  return (
    <ToolbarButton
      {...props}
      aria-busy={pending !== null}
      disabled={!canUndo}
      onClick={undo}
      tooltip="Undo"
    >
      <IconPlaceholder lucide="Undo2Icon" tabler="IconArrowBackUp" hugeicons="Undo02Icon" phosphor="ArrowUUpLeftIcon" remixicon="RiArrowGoBackLine" className="[&:dir(rtl)]:-scale-x-100" />
    </ToolbarButton>
  );
}
